44: /* ── State & storage ─────────────────────────────────────── */
45: function createState(family) {
46:   return {
47:     familyId: family.id,
48:     cash: family.cash,
49:     day: 1,
50:     happiness: family.happiness,
51:     prestige: family.prestige,
52:     lastMomentDay: 0,
53:     trips: [],
54:     history: [
55:       {
56:         day: 1,
57:         title: 'The house is ready',
58:         detail: `${family.house.name} prepared for the family.`,
59:       },
60:     ],
61:   };
62: }
63: 
64: function getState(id) {
65:   if (!states[id]) states[id] = createState(familyById(id));
66:   return states[id];
67: }
68: 
69: function loadSave() {
70:   try {
71:     const raw = localStorage.getItem(SAVE_KEY);
72:     if (!raw) return null;
73:     const parsed = JSON.parse(raw);
74:     if (!parsed || !parsed.states) return null;
75:     return parsed;
76:   } catch {
77:     return null;
78:   }
79: }
80: 
81: function hydrateFromSave() {
82:   if (!saveData) return;
83:   if (FAMILIES.some((f) => f.id === saveData.activeId)) activeId = saveData.activeId;
84:   FAMILIES.forEach((f) => {
85:     const saved = saveData.states?.[f.id];
86:     if (saved) {
87:       states[f.id] = { ...createState(f), ...saved, trips: saved.trips || [], history: saved.history || [] };
88:     }
89:   });
90:   if (saveData.started) {
91:     started = true;
92:     $('resume-btn').classList.remove('hidden');
93:     $('resume-btn').textContent = compactLabel()
94:       ? `Resume ${familyById(activeId).surname}`
95:       : `Resume the ${familyById(activeId).surname} story`;
96:   }
97: }
98: 
99: function saveGame() {
100:   try {
101:     localStorage.setItem(
102:       SAVE_KEY,
103:       JSON.stringify({
104:         v: 1,
105:         activeId,
106:         started,
107:         states,
108:         savedAt: Date.now(),
109:       })
110:     );
111:   } catch {
112:     /* private-mode storage is allowed to fail silently */
113:   }
114: }
115: 
116: function state() {
117:   return getState(activeId);
118: }
119: 
120: function family() {
121:   return familyById(activeId);
122: }
