124: /* ── Formatting helpers ──────────────────────────────────── */
125: function formatCompact(n) {
126:   if (Math.abs(n) >= 1_000_000_000) return `$${(n / 1_000_000_000).toFixed(2).replace(/\.?0+$/, '')}B`;
127:   if (Math.abs(n) >= 1_000_000) return `$${(n / 1_000_000).toFixed(n >= 10_000_000 ? 1 : 2).replace(/\.?0+$/, '')}M`;
128:   if (Math.abs(n) >= 10_000) return `$${Math.round(n / 1_000)}K`;
129:   return formatMoney(n);
130: }
131: 
132: function parseLoose(str) {
133:   const value = parseFloat(String(str).replace(/[^0-9.]/g, '')) || 0;
134:   if (/B/i.test(str)) return value * 1_000_000_000;
135:   if (/M/i.test(str)) return value * 1_000_000;
136:   if (/K/i.test(str)) return value * 1_000;
137:   return value;
138: }
139: 
140: function dayLabel(s) {
141:   return `${WEEKDAYS[(Math.max(1, s.day) - 1) % 7]} · DAY ${s.day}`;
142: }
143: 
144: function moodLabel(s) {
145:   return MOOD_LABELS[(Math.max(1, s.day) - 1) % MOOD_LABELS.length];
146: }
147: 
148: function tripPrice(dest, cabinId) {
149:   const cabin = CABINS[cabinId] || CABINS.economy;
150:   return Math.round((dest.base * cabin.multiplier) / 10) * 10;
151: }
