153: /* ── Icons and static UI ─────────────────────────────────── */
154: function hydrateIcons(root = document) {
155:   root.querySelectorAll('[data-icon]').forEach((el) => {
156:     if (!el.dataset.iconReady) {
157:       el.innerHTML = icon(el.dataset.icon);
158:       el.dataset.iconReady = '1';
159:     }
160:   });
161: }
162: hydrateIcons();
