169: function toast(title, message = '', glyph = '✦') {
170:   const stack = $('toast-stack');
171:   const el = document.createElement('div');
172:   el.className = 'toast';
173:   el.innerHTML = `<div class="toast-icon">${glyph}</div><div><b>${title}</b>${message ? `<p>${message}</p>` : ''}</div>`;
174:   stack.appendChild(el);
175:   setTimeout(() => {
176:     el.classList.add('leaving');
177:     setTimeout(() => el.remove(), 380);
178:   }, 4300);
179: }
