181: /* ── Selection screen ────────────────────────────────────── */
182: function renderPicker() {
183:   const picker = $('family-picker');
184:   picker.innerHTML = FAMILIES.map(
185:     (f) => `
186:     <button class="family-option ${f.id === activeId ? 'active' : ''}" data-family="${f.id}" role="listitem" style="--family-accent:${f.accent}">
187:       <span class="family-index">${f.order}</span>
188:       <span class="family-option-copy">
189:         <b>${f.familyName}</b>
190:         <small><span class="tier-dot" style="--family-accent:${f.accent}"></span>${f.tier}${f.id === 'average' ? ' · NO CONNECTIONS' : ''}</small>
191:       </span>
192:       <span class="family-money"><b>${formatCompact(f.cash)}</b><small>available</small></span>
193:     </button>`
194:   ).join('');
195: 
196:   picker.querySelectorAll('.family-option').forEach((btn) => {
197:     btn.addEventListener('click', () => previewFamily(btn.dataset.family));
198:   });
199: }
200: 
201: function previewFamily(id) {
202:   if (!FAMILIES.some((f) => f.id === id) || id === activeId) return;
203:   activeId = id;
204:   const f = family();
205:   renderPicker();
206:   $('enter-btn').innerHTML = enterLabel(f);
207:   $('preview-label').innerHTML = `<span class="preview-index">${f.order}</span><span class="preview-copy"><b>${f.house.name}</b><small>${f.house.location}</small></span>`;
208:   $('scene').style.opacity = '0.25';
209:   setTimeout(() => {
210:     world.setFamily(f, 'select', false);
211:     requestAnimationFrame(() => {
212:       $('scene').style.opacity = '1';
213:     });
214:   }, 70);
