218:   hydrateFromSave();
219:   renderPicker();
220:   const f = family();
221:   $('enter-btn').innerHTML = enterLabel(f);
222:   $('preview-label').innerHTML = `<span class="preview-index">${f.order}</span><span class="preview-copy"><b>${f.house.name}</b><small>${f.house.location}</small></span>`;
