229: /* ── HUD ─────────────────────────────────────────────────── */
230: function renderHUD() {
231:   const f = family();
232:   const s = state();
233:   $('crest').textContent = f.crest;
234:   $('family-name').textContent = compactLabel() ? f.surname : f.familyName;
235:   $('family-tier').textContent = f.tier.toUpperCase();
236:   $('cash-value').textContent = formatMoney(s.cash);
237:   $('income-value').textContent = `+${formatCompact(f.dailyIncome)} / day`;
238:   $('day-label').textContent = dayLabel(s);
239:   $('time-label').textContent = moodLabel(s);
240:   $('house-name').textContent = f.house.name;
241:   $('house-location').textContent = f.house.location;
242:   $('mood-line').textContent = f.mood;
243:   $('happy-value').textContent = s.happiness;
244:   $('prestige-value').textContent = s.prestige;
245:   $('happy-bar').style.width = `${s.happiness}%`;
246:   $('prestige-bar').style.width = `${s.prestige}%`;
247:   $('game-ui').style.setProperty('--family-accent', f.accent);
248: 
249:   const used = s.lastMomentDay === s.day;
250:   const moment = $('moment-btn');
251:   moment.disabled = used;
252:   moment.querySelector('b').textContent = used ? 'A quiet moment taken' : 'Take in the sunset';
253:   moment.querySelector('small').textContent = used ? 'Come back tomorrow' : '+5 happiness · once a day';
254: 
255:   document.title = `${f.house.name} · Heirloom`;
256: }
