277: function startGame({ resume = false } = {}) {
278:   const f = family();
279:   const s = state();
280:   started = true;
281:   saveGame();
282:   $('select-screen').classList.add('leaving');
283:   setTimeout(() => $('select-screen').classList.add('hidden'), 420);
284:   $('game-ui').classList.remove('hidden');
285:   world.setFamily(f, 'home', true);
286:   world.setDayMood(s.day);
287:   renderHUD();
288:   world.controls.autoRotate = false;
289:   world.controls.enabled = true;
290:   if (!resume) showIntro(f);
291:   showTutorial();
292:   sound.chime();
293:   if (resume) toast('Welcome back', `${f.house.name} has been kept exactly as you left it.`, '⌂');
294: }
