296: /* ── Day & moment ────────────────────────────────────────── */
297: function advanceDay() {
298:   if (currentTrip) return;
299:   closePanel();
300:   const f = family();
301:   const s = state();
302:   const income = f.dailyIncome;
303:   s.cash += income;
304:   s.day += 1;
305:   s.lastMomentDay = 0;
306:   s.happiness = Math.max(42, s.happiness - 1);
307:   s.history.unshift({
308:     day: s.day,
309:     title: 'Daily income collected',
310:     detail: `${formatMoney(income)} from salary, businesses and investments.`,
311:   });
312:   if (s.history.length > 18) s.history.length = 18;
313:   world.setDayMood(s.day);
314:   renderHUD();
315:   saveGame();
316:   sound.cash();
317:   showDayBreak(s.day, income, f);
318:   toast(`Day ${s.day} · income collected`, `+${formatMoney(income)} added to available funds.`, '↻');
319: }
320: 
321: function showDayBreak(day, income, f) {
322:   const el = document.createElement('div');
323:   el.className = 'day-transition';
324:   el.innerHTML = `
325:     <div class="day-break-kicker">${WEEKDAYS[(day - 1) % 7]} · DAY ${day}</div>
326:     <div class="day-break-title">A new day at<br><em>${f.house.name}</em></div>
327:     <div class="day-break-income">+${formatMoney(income)}</div>
328:     <div class="day-break-sub">collected from the household portfolio</div>`;
329:   app.appendChild(el);
330:   setTimeout(() => el.classList.add('leaving'), reducedMotion ? 350 : 1900);
331:   setTimeout(() => el.remove(), reducedMotion ? 700 : 2500);
332: }
333: 
334: function takeMoment() {
335:   const s = state();
336:   if (s.lastMomentDay === s.day) {
337:     toast('Already taken', 'This moment belongs to today. A new one arrives tomorrow.', '☀');
338:     return;
339:   }
340:   s.happiness = Math.min(100, s.happiness + 5);
341:   s.lastMomentDay = s.day;
342:   s.history.unshift({ day: s.day, title: 'A moment at home', detail: 'The family took in the last light together. +5 happiness.' });
343:   renderHUD();
344:   saveGame();
345:   sound.chime();
346:   toast('Happiness +5', 'The terrace was quiet. Nobody reached for a phone.', '☀');
347:   if (ui.panel === 'estate') renderPanelBody('estate');
348: }
