350: /* ── Panels ──────────────────────────────────────────────── */
351: const PANEL_META = {
352:   estate: { kicker: 'BACK AT THE HOUSE', title: null, subtitle: 'A private world, arranged exactly so.' },
353:   family: { kicker: 'THE HOUSEHOLD', title: null, subtitle: 'The people behind the name.' },
354:   assets: { kicker: 'THE PORTFOLIO', title: 'Everything, preselected', subtitle: 'A complete life, chosen for this family.' },
355:   travel: { kicker: 'THE GETAWAY', title: 'Where to next?', subtitle: 'Ten cities. Three ways to arrive.' },
356:   ledger: { kicker: 'THE BOOKS', title: 'Quietly managed', subtitle: 'Income, work and the cost of a life.' },
357: };
358: 
359: function openPanel(view = 'estate') {
360:   if (currentTrip) return;
361:   ui.panel = view;
362:   const f = family();
363:   const meta = PANEL_META[view];
364:   $('panel-kicker').innerHTML = `<span class="eyebrow-line"></span>${meta.kicker}`;
365:   $('panel-title').textContent = view === 'family' ? f.familyName : view === 'estate' ? f.house.name : meta.title;
366:   $('panel-subtitle').textContent = view === 'estate' ? `${f.house.location} · ${f.house.style}` : meta.subtitle;
367:   $('panel').classList.remove('hidden');
368:   $('panel').setAttribute('aria-hidden', 'false');
369:   $('panel-body').scrollTop = 0;
370:   world.controls.enabled = false;
371:   renderPanelBody(view);
372:   document.querySelectorAll('.dock-item').forEach((b) => b.classList.toggle('active', b.dataset.view === view));
373:   sound.click();
374: }
375: 
376: function closePanel() {
377:   if ($('panel').classList.contains('hidden')) return;
378:   $('panel').classList.add('hidden');
379:   $('panel').setAttribute('aria-hidden', 'true');
380:   ui.panel = null;
381:   world.controls.enabled = true;
382:   document.querySelectorAll('.dock-item').forEach((b) => b.classList.toggle('active', b.dataset.view === 'estate'));
383: }
384: 
385: function renderPanelBody(view) {
386:   const body = $('panel-body');
387:   const f = family();
388:   const s = state();
389:   if (view === 'estate') body.innerHTML = estatePanel(f, s);
390:   if (view === 'family') body.innerHTML = familyPanel(f, s);
391:   if (view === 'assets') body.innerHTML = assetsPanel(f, s);
392:   if (view === 'travel') body.innerHTML = travelPanel(f, s);
393:   if (view === 'ledger') body.innerHTML = ledgerPanel(f, s);
394:   hydrateIcons(body);
395:   bindPanelActions(view);
396: }
397: 
398: function bindPanelActions(view) {
399:   const body = $('panel-body');
400:   const momentBtn = body.querySelector('#panel-moment');
401:   if (momentBtn) momentBtn.addEventListener('click', takeMoment);
402: 
403:   const switchBtn = body.querySelector('#switch-household-btn');
404:   if (switchBtn) switchBtn.addEventListener('click', openSwitch);
405: 
406:   const endDay = body.querySelector('#panel-end-day');
407:   if (endDay) endDay.addEventListener('click', advanceDay);
408: 
409:   if (view === 'travel') {
410:     body.querySelectorAll('[data-destination]').forEach((btn) => {
411:       btn.addEventListener('click', () => {
412:         ui.selectedDestination = btn.dataset.destination;
413:         ui.selectedCabin = family().travel.defaultCabin;
414:         renderPanelBody('travel');
415:         requestAnimationFrame(() => {
416:           document.getElementById('destination-detail')?.scrollIntoView({ behavior: reducedMotion ? 'auto' : 'smooth', block: 'nearest' });
417:         });
418:       });
419:     });
420: 
421:     body.querySelectorAll('[data-cabin]').forEach((btn) => {
422:       btn.addEventListener('click', () => {
423:         ui.selectedCabin = btn.dataset.cabin;
424:         renderPanelBody('travel');
425:         requestAnimationFrame(() => {
426:           document.getElementById('destination-detail')?.scrollIntoView({ behavior: reducedMotion ? 'auto' : 'smooth', block: 'nearest' });
427:         });
428:       });
429:     });
430: 
431:     const book = body.querySelector('#book-trip');
432:     if (book) {
433:       book.addEventListener('click', () => {
434:         const f = family();
435:         const s = state();
436:         const dest = DESTINATIONS.find((d) => d.id === ui.selectedDestination);
437:         if (!dest) return;
438:         const cabinId = ui.selectedCabin || f.travel.defaultCabin;
439:         const price = tripPrice(dest, cabinId);
440:         if (s.cash < price) {
441:           toast('Not quite yet', `You need ${formatMoney(price - s.cash)} more. End a few days to collect income.`, '◷');
442:           return;
443:         }
444:         startTrip(dest, cabinId, price);
445:       });
446:     }
447:   }
448: }
