450: function memberCard(m) {
451:   return `
452:     <article class="member-card" style="--m-top:${m.top};--m-bottom:${m.bottom}">
453:       <div class="member-top">
454:         <div class="member-avatar">${m.name[0]}</div>
455:         <div class="member-name"><b>${m.name}</b><small>${m.age} years old</small></div>
456:       </div>
457:       <p class="member-role">${m.role}</p>
458:       <div class="member-outfit">${m.outfit}</div>
459:       <span class="member-chip">${m.style === 'child' ? 'Youngest generation' : m.style === 'gown' ? 'Heir apparent' : 'Household'}</span>
460:     </article>`;
461: }
462: 
463: function houseVisual(f) {
464:   return `
465:     <div class="house-visual">
466:       <div class="hv-kicker">THE RESIDENCE · ${f.house.value > 1_000_000 ? formatCompact(f.house.value) : formatMoney(f.house.value)}</div>
467:       <h3>${f.house.name}</h3>
468:       <p>${f.house.blurb}</p>
469:       <div class="house-specs">
470:         <div class="spec"><small>Location</small><b>${f.house.location}</b></div>
471:         <div class="spec"><small>Interior</small><b>${f.house.area}</b></div>
472:         <div class="spec"><small>Bedrooms</small><b>${f.house.beds} · ${f.house.baths} baths</b></div>
473:         <div class="spec"><small>Staff</small><b>${f.house.staff === 0 ? 'The family itself' : `${f.house.staff} in residence`}</b></div>
474:       </div>
475:     </div>`;
476: }
477: 
478: function estatePanel(f, s) {
479:   return `
480:     <section class="panel-section">
481:       ${houseVisual(f)}
482:     </section>
483:     <section class="panel-section split">
484:       <div class="panel-card">
485:         <span class="section-label">HOUSEHOLD PULSE</span>
486:         <div class="stat-big-grid">
487:           <div class="stat-big"><small>HAPPINESS</small><b>${s.happiness}</b><i>at home</i></div>
488:           <div class="stat-big"><small>STANDING</small><b>${s.prestige}</b><i>in the world</i></div>
489:           <div class="stat-big"><small>PRIVACY</small><b>${f.privacy}</b><i>very protected</i></div>
490:           <div class="stat-big"><small>TRIPS</small><b>${s.trips.length}</b><i>taken together</i></div>
491:         </div>
492:         <button id="panel-moment" class="moment-btn" ${s.lastMomentDay === s.day ? 'disabled' : ''} style="margin-top:14px">
493:           <span class="moment-icon">☀</span>
494:           <span><b>${s.lastMomentDay === s.day ? 'A quiet moment taken' : 'Take in the sunset'}</b><small>${s.lastMomentDay === s.day ? 'Come back tomorrow' : '+5 happiness · once a day'}</small></span>
495:         </button>
496:       </div>
497:       <div class="panel-card warm">
498:         <span class="section-label">THE FAMILY CREED</span>
499:         <p class="profile-quote">“${f.philosophy}”</p>
500:         <div style="margin-top:16px">
501:           <div class="profile-line"><span>Connections</span><b>${f.connections}</b></div>
502:           <div class="profile-line"><span>Household</span><b>${f.members.length} people</b></div>
503:           <div class="profile-line"><span>Today</span><b>${moodLabel(s)}</b></div>
504:           <div class="profile-line"><span>Liquid funds</span><b>${formatMoney(s.cash)}</b></div>
505:         </div>
506:       </div>
507:     </section>
508:     <section class="panel-section">
509:       <div class="section-head"><h3>The household</h3><p>Tap Family in the dock for every detail</p></div>
510:       <div class="member-grid">${f.members.map(memberCard).join('')}</div>
511:     </section>`;
512: }
513: 
514: function familyPanel(f, s) {
515:   return `
516:     <section class="panel-section">
517:       <div class="stat-big-grid">
518:         <div class="stat-big"><small>HAPPINESS</small><b>${s.happiness}</b><i>household mood</i></div>
