748: function startTrip(dest, cabinId, price) {
749:   const f = family();
750:   const s = state();
751:   const cabin = CABINS[cabinId];
752:   const happiness = cabinId === 'first' ? 16 : cabinId === 'business' ? 12 : 8;
753:   const standing = cabinId === 'first' ? 6 : cabinId === 'business' ? 3 : 1;
754:   s.cash -= price;
755:   s.happiness = Math.min(100, s.happiness + happiness);
756:   s.prestige = Math.min(100, s.prestige + standing);
757:   s.history.unshift({
758:     day: s.day,
759:     title: `${cabin.label} to ${dest.city}`,
760:     detail: `${formatMoney(price)} · ${f.travel.aircraft} · +${happiness} happiness.`,
761:   });
762:   if (s.history.length > 18) s.history.length = 18;
763:   s.trips.unshift({ destination: dest.id, cabin: cabinId, price, day: s.day, happiness, standing });
764:   if (s.trips.length > 12) s.trips.length = 12;
765:   currentTrip = { dest, cabinId, price, happiness, standing, origin: ORIGINS[f.id] };
766:   renderHUD();
767:   saveGame();
768:   closePanel();
769:   $('game-ui').classList.add('hidden');
770:   $('vacation-screen').classList.add('hidden');
771:   beginFlight();
772: }
