774: function beginFlight() {
775:   if (!currentTrip) return;
776:   const trip = currentTrip;
777:   const f = family();
778:   const cabin = CABINS[trip.cabinId];
779:   world.showFlight(f, trip.dest);
780: 
781:   $('flight-screen').classList.remove('hidden');
782:   $('flight-class-label').textContent = `${cabin.label.toUpperCase()} CLASS`;
783:   $('flight-from').textContent = trip.origin.code;
784:   $('flight-to').textContent = trip.dest.code;
785:   $('flight-route-label').textContent = `${trip.origin.city.toUpperCase()} → ${trip.dest.city.toUpperCase()}`;
786:   $('flight-duration').textContent = trip.dest.hours;
787:   $('flight-perks').innerHTML = cabin.perks.map((p) => `<span>${p}</span>`).join('');
788:   $('flight-status-text').textContent = 'Wheels up.';
789:   $('flight-percent').textContent = '0%';
790:   $('flight-progress-bar').style.width = '0%';
791:   const plane = document.querySelector('.route-plane');
792:   if (plane) plane.style.left = '0%';
793: 
794:   const token = ++flightToken;
795:   const duration = reducedMotion ? 1200 : 6200;
796:   const start = performance.now();
797:   sound.swoosh();
798: 
799:   const frame = (now) => {
800:     if (token !== flightToken || !currentTrip) return;
801:     const p = Math.min(1, (now - start) / duration);
802:     const percent = Math.round(p * 100);
803:     $('flight-progress-bar').style.width = `${percent}%`;
804:     $('flight-percent').textContent = `${percent}%`;
805:     if (plane) plane.style.left = `${percent}%`;
806: 
807:     let status = 'Wheels up.';
808:     if (percent > 16) status = 'Climbing to cruise.';
809:     if (percent > 36) status = 'Somewhere over the ocean.';
810:     if (percent > 58) status = 'Cabin lights dim. Dinner is served.';
811:     if (percent > 78) status = 'Beginning the descent.';
812:     if (percent > 93) status = `Arriving in ${trip.dest.city}.`;
813:     $('flight-status-text').textContent = status;
814: 
815:     if (p < 1) requestAnimationFrame(frame);
816:     else finishFlight();
817:   };
818:   requestAnimationFrame(frame);
819: }
