713:   const baseMat = std(isAverage ? 0x4c4a3e : 0x4e4b40, 0.96);
714:   const islandBody = cyl(isUltra ? 22 : 20, isUltra ? 19.2 : 17.5, 1.2, 64, baseMat, 0, -0.62, 0, false);
715:   islandBody.receiveShadow = true;
