722:   lawn.position.y = 0.005;
723:   lawn.receiveShadow = true;
724:   island.add(lawn);
725: 
726:   // soft irregular lawn patches for painterly feel
727:   for (let i = 0; i < 12; i++) {
728:     const a = (i / 12) * TAU + 0.3;
729:     const r = 12 + (i % 4) * 1.5;
730:     const patch = new THREE.Mesh(new THREE.CircleGeometry(1.8 + (i % 3) * 0.65, 7), std(palette.lawnAlt, 0.98));
731:     patch.rotation.x = -Math.PI / 2;
732:     patch.position.set(Math.cos(a) * r, 0.012, Math.sin(a) * r);
733:     patch.scale.set(1.5, 1, 0.75);
