744:       island.add(line);
745:     }
746:   }
747: 
748:   // stepping path and driveway
749:   const pathMat = std(isAverage ? 0xa99d86 : 0x8b7f6b, 0.9);
750:   for (let i = 0; i < 4; i++) {
751:     island.add(box(2.4 - i * 0.12, 0.1, 1.2, pathMat, 0, 0.07, 12.5 + i * 1.35, false));
752:   }
