754:   drive.rotation.y = isAverage ? 0.1 : -0.16;
755:   island.add(drive);
756: 
757:   // trim hedges / borders
758:   if (!isAverage) {
759:     hedge(island, -12.5, 0.1, 0.8, 4.2, 0.6, 0.7);
760:     hedge(island, 13.3, 0.1, -2.2, 0.55, 3.6, 0.55);
