767: 
768:   // trees
769:   const treeSpots = isUltra
770:     ? [[-14.5, -3], [15.5, 11.5], [-15.4, 12.6], [12.9, -12.7], [-7.5, -13.4], [17.6, -7.0]]
771:     : isAverage
772:       ? [[-10.5, 1.2], [10.2, 4.4], [-8.4, 11.4], [7.5, 12.1]]
