807: 
808:   // water sparkle
809:   const glintMat = new THREE.MeshBasicMaterial({ color: 0xffe5b0, transparent: true, opacity: 0.35, side: THREE.DoubleSide, depthWrite: false });
810:   for (let i = 0; i < 5; i++) {
